replace(r'Same equal-energy subset; pre-update predictions vs.\ logged proxy reward; pooled across targets. Full-sample proxies: \namedref{Table}{tab:logged_calibration}.',r'265-mutation subset; pooled proxy reward; see \namedref{Table}{tab:logged_calibration}.')
