j=json.loads((A/'manifest.json').read_text());j['abstract_words']=len(abstract.split());j['paragraph_edits']=len(changes);j['narrative_count_correction']={'source':'filled_mechanism_data_20260930.json','E_candidates':[735,746],'E_trials':[734,745],'E_rejects':[725,736]};(A/'manifest.json').write_text(json.dumps(j,indent=2,ensure_ascii=False)+'\n')
